import { Audio } from "@remotion/media";
import { Sequence, staticFile, useVideoConfig } from "remotion";

/**
 * The audio bed and the three UI sounds, keyed to the beat sheet in §7 of
 * `promo/BRIEF.md`.
 *
 * There is no voiceover — that was a decision, not an omission (see §0). So the
 * caption is the narration, and the audio only has to carry the mechanics.
 *
 * Every sound here is procedurally generated by `promo/make-audio.py`, so
 * nothing in this cut is licensed from anywhere and the whole mix is
 * reproducible from source.
 */
export const HeroAudio: React.FC = () => {
  const { fps } = useVideoConfig();

  /** Cue frames, in the hero's 900-frame timeline. */
  const CUES = {
    pip: 5, // the hook lands
    alarm: 15, // 429 hits the primary
    thunk: 44, // traffic moves to the next provider
    tick: 55, // cache hit
    tick2: 58,
  } as const;

  return (
    <>
      <Audio src={staticFile("audio/bed30-pulse.wav")} volume={0.5} loop />
      <Sequence from={CUES.pip * fps}>
        <Audio src={staticFile("audio/pip.wav")} volume={0.35} />
      </Sequence>
      <Sequence from={CUES.alarm * fps}>
        <Audio src={staticFile("audio/alarm.wav")} volume={0.4} />
      </Sequence>
      <Sequence from={CUES.thunk * fps}>
        <Audio src={staticFile("audio/thunk.wav")} volume={0.5} />
      </Sequence>
      <Sequence from={CUES.tick * fps}>
        <Audio src={staticFile("audio/tick.wav")} volume={0.28} />
      </Sequence>
      <Sequence from={CUES.tick2 * fps}>
        <Audio src={staticFile("audio/tick.wav")} volume={0.2} />
      </Sequence>
    </>
  );
};

/** The bumper gets the same bed and its own cue timing. */
export const BumperAudio: React.FC = () => {
  const { fps } = useVideoConfig();

  const CUES = {
    alarm: 16, // 429 hits the primary
    thunk: 44, // failover
  } as const;

  return (
    <>
      <Audio src={staticFile("audio/bed30.wav")} volume={0.5} loop />
      <Sequence from={CUES.alarm * fps}>
        <Audio src={staticFile("audio/alarm.wav")} volume={0.4} />
      </Sequence>
      <Sequence from={CUES.thunk * fps}>
        <Audio src={staticFile("audio/thunk.wav")} volume={0.5} />
      </Sequence>
    </>
  );
};

/**
 * The 60s master. Same generator, same cues — shifted to the new timeline.
 *
 * The problem section is deliberately almost silent: a low bed only, so the
 * first twenty seconds feel like a room with nobody talking in it. The alarm
 * lands on the third pain, which is the one the gateway fixes, so the sound and
 * the argument turn at the same moment.
 */
export const MasterAudio: React.FC = () => {
  const { fps } = useVideoConfig();

  /** Cue frames, in the master's 1740-frame timeline. */
  const CUES = {
    alarm: 16, // the 429, in problem panel 1
    alarm2: 17, // panel 2 (same bed, held)
    thunk: 44, // panel 3 — the pain the fix answers
    turn: 24, // "three problems. one address."
    pip: 28, // the hook lands
    thunk2: 44, // traffic moves to the next provider
    tick: 55, // cache hit
    tick2: 58,
  } as const;

  return (
    <>
      {/* Quieter and unpulsed for the problem section: 24 seconds of a room
          with nobody talking in it, then the bed picks up its tick. */}
      <Audio
        src={staticFile("audio/bed30.wav")}
        volume={0.32}
        loop
      />
      <Sequence from={CUES.alarm * fps}>
        <Audio src={staticFile("audio/alarm.wav")} volume={0.34} />
      </Sequence>
      <Sequence from={CUES.thunk * fps}>
        <Audio src={staticFile("audio/thunk.wav")} volume={0.42} />
      </Sequence>
      <Sequence from={CUES.turn * fps}>
        <Audio src={staticFile("audio/pip.wav")} volume={0.3} />
      </Sequence>
      <Sequence from={24 * fps}>
        <Audio src={staticFile("audio/bed30-pulse.wav")} volume={0.42} loop />
      </Sequence>
      <Sequence from={CUES.tick * fps}>
        <Audio src={staticFile("audio/tick.wav")} volume={0.22} />
      </Sequence>
      <Sequence from={CUES.tick2 * fps}>
        <Audio src={staticFile("audio/tick.wav")} volume={0.16} />
      </Sequence>
    </>
  );
};

/**
 * The Story cut. 15 seconds, no music bed under the proof — a Story is watched
 * muted by default, so the mix leans on the two cues that survive muting: the
 * landing thud on the claim and the tick as the number resolves.
 */
export const StoryAudio: React.FC = () => {
  const { fps } = useVideoConfig();

  const CUES = {
    thunk: 8, // the claim lands
    tick: 54, // the billed figure resolves
  } as const;

  return (
    <>
      <Audio src={staticFile("audio/bed30.wav")} volume={0.28} loop />
      <Sequence from={CUES.thunk * fps}>
        <Audio src={staticFile("audio/thunk.wav")} volume={0.5} />
      </Sequence>
      <Sequence from={CUES.tick * fps}>
        <Audio src={staticFile("audio/tick.wav")} volume={0.26} />
      </Sequence>
    </>
  );
};
